-- 栈基础：固定入栈顺序的合法出栈序列模拟。
INSERT INTO knowledge_point (name,description,course_id,parent_id,content_key,content_source,content_version,content_review_status,sort_order,deleted)
SELECT '合法出栈序列','按固定入栈顺序模拟辅助栈，只有当前栈顶匹配目标时才能弹出。',course.id,parent.id,'cs408-stack-pop-sequences','AISTU',1,'REVIEWED',4,0 FROM course JOIN knowledge_point parent ON parent.course_id=course.id AND parent.content_key='408-stacks-queues-arrays' LEFT JOIN knowledge_point existing ON existing.content_key='cs408-stack-pop-sequences' WHERE course.content_key='cs408-data-structures' AND existing.id IS NULL;
INSERT INTO tutor_content (knowledge_point_id,content_key,content_version,review_status,title,lesson_json,check_json)
SELECT point.id,'cs408-stack-pop-sequences',1,'REVIEWED','合法出栈序列',JSON_OBJECT('summary','判断固定入栈顺序能否产生目标出栈序列时，按输入顺序模拟辅助栈；每次栈顶等于目标当前元素就反复弹出。全部目标元素匹配才合法，已被上层元素压住且输入位置越过的元素不能越过它先弹出。','steps',JSON_ARRAY('按给定顺序逐个压入辅助栈','每次检查当前栈顶是否匹配目标','匹配时反复弹出并推进目标位置','输入耗尽后仍有未匹配目标则非法','模拟过程不允许越过栈顶元素'),'prerequisite',JSON_OBJECT('contentKey','cs408-stack-lifo','title','栈的 LIFO 语义与基本操作','description','先掌握只能从栈顶弹出的 LIFO 限制。')),JSON_OBJECT('id','stack-pop-sequences-v1','prompt','判断合法出栈序列的可靠方法是什么？','options',JSON_ARRAY(JSON_OBJECT('id','SIMULATE_TOP','text','按入栈顺序模拟，并仅在栈顶匹配目标时弹出'),JSON_OBJECT('id','SORT_TARGET','text','先把目标出栈序列排序再比较')),'correctOptionId','SIMULATE_TOP','correctExplanation','正确：辅助栈模拟直接保留每个时刻的栈顶限制。','incorrectExplanation','不正确：排序会丢失目标序列的先后关系，不能判断栈操作是否可达。') FROM knowledge_point point LEFT JOIN tutor_content existing ON existing.content_key='cs408-stack-pop-sequences' AND existing.content_version=1 WHERE point.content_key='cs408-stack-pop-sequences' AND existing.id IS NULL;
